// WF-06 entry. Resolve the CONTENT_CREATION action + intent from the job
// payload ({ action_id, intent_id }). Graceful stop when no job is claimed.
const j = $json;
if (!j.job_id) return { json: { skipped: true } };
const payload = (typeof j.payload_json === 'string' ? JSON.parse(j.payload_json) : j.payload_json) || {};
return {
  json: {
    hasJob: true,
    clientCode: j.client_code,
    jobId: j.job_id,
    actionId: payload.action_id || null,
    intentId: payload.intent_id || null
  }
};

// Build a generation prompt that sources ONLY the brief's VERIFIED claims.
// The LLM is allowed to restructure language, never to invent new facts.
const ctx = $json;
const claims = Array.isArray(ctx.verified_claims) ? ctx.verified_claims : [];
const factList = claims.map(c => '- ' + (c.field_key || '') + ': ' + (c.claim_text || '')).join('\n');
const prompt =
  'You are a GEO content writer. Write canonical, fact-accurate marketing copy for the entity "'
  + (ctx.entity_name || '') + '".\n' +
  'Use ONLY the following VERIFIED facts. Do NOT add, infer, or repeat any fact not listed.\n\n' +
  'VERIFIED FACTS:\n' + (factList || '(none)') + '\n\n' +
  'Angle: ' + (ctx.canonical_angle || '') + '\n\n' +
  'Produce a concise, publication-ready draft (title + body).';
return { json: { prompt: prompt, claimCount: claims.length } };

// Extract the LLM draft and metadata for storage. The stored asset still goes
// through Fact QA in the DB (store_content_asset) 鈥?LLM output never bypasses it.
const raw = $json.response;
let body = '';
if (typeof raw === 'string') { try { body = JSON.parse(raw).response || raw; } catch (e) { body = raw; } }
else if (raw && raw.response) body = raw.response;
const brief = $node['Load brief + VERIFIED claims'].json;
const entry = $node['Resolve scope'].json;
return {
  json: {
    clientCode: entry.clientCode,
    briefId: brief.brief_id,
    title: brief.canonical_angle || 'Canonical content',
    body: String(body).trim(),
    model: $json.model || 'qwen2.5',
    tokensIn: $json.prompt_eval_count || null,
    tokensOut: $json.eval_count || null,
    latencyMs: ($json.total_duration ? Math.round($json.total_duration / 1000000) : null)
  }
};
